#include <stdio.h>

/* teste do desafio leitor-de-notas — counter_protocol (03-tdd 3.9.3).
   Cada cenario escreve num arquivo o que a pessoa digitaria, aponta o stdin
   para esse arquivo (freopen) e captura o stdout no proprio cenario. Os
   nomes dos temporarios sao POR CENARIO: um cenario nunca le a entrada nem
   a captura do outro. Nunca ha fclose de stdin/stdout — so fflush — para o
   segundo freopen ficar legal (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void leitorDeNotas(void);

SM_TEST(quatro_notas_de_tras_para_frente) {
    /* o que a pessoa digita: 4 notas, e depois as quatro */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "4\n7 2 9 4\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    leitorDeNotas();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a ultima nota lida vem primeiro", linha, "4\n",
              "a gaveta 3 guardou o 4, e a impressao comeca pela ultima gaveta");
    fgets(linha, 80, f);
    checa_str("a segunda linha invertida", linha, "9\n",
              "descendo o indice, a gaveta 2 guardou o 9");
    fgets(linha, 80, f);
    checa_str("a terceira linha invertida", linha, "2\n",
              "a gaveta 1 guardou o 2");
    fgets(linha, 80, f);
    checa_str("a primeira nota lida vem por ultimo", linha, "7\n",
              "a gaveta 0 guardou o 7 e sai na ultima linha");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "foram quatro notas: a saida acaba na quarta linha");
    fclose(f);
}

SM_TEST(so_tres_notas_so_tres_linhas) {
    /* agora o n digitado e 3: a saida tem de encurtar junto */
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "3\n5 1 8\n");
