#include <stdio.h>

void leitorDeNotas(void) {
    int notas[50] = {0};
    int n = 0;

    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &notas[i]);
    }

    for (int i = n - 1; i >= 0; i--) {
        printf("%d\n", notas[i]);
    }
}
